21	/**
22	 * Parse JSONL transcript into individual messages
23	 */
24	function parseTranscriptMessages(
25	  jsonl: string,
26	  sessionId: string,
27	  checkpointId: string
28	): Message[] {
29	  const lines = jsonl.split("\n").filter((line) => line.trim());
30	  const messages: Message[] = [];
