45	            ? entry.message.content
46	            : JSON.stringify(entry.message.content),
47	          message_index: messageIndex++,
48	          timestamp: entry.timestamp ? new Date(entry.timestamp).getTime() : undefined,
49	        });
50	      }
51	
52	      // Assistant messages
53	      else if (entry.type === "assistant" && entry.message?.content) {
54	        if (Array.isArray(entry.message.content)) {
55	          for (const block of entry.message.content) {
56	            // Text content
57	            if (block.type === "text" && block.text) {
58	              messages.push({
59	                session_id: sessionId,
60	                checkpoint_id: checkpointId,
61	                message_type: "assistant",
62	                role: "assistant",
63	                content: block.text,
64	                message_index: messageIndex++,
65	                timestamp: entry.timestamp ? new Date(entry.timestamp).getTime() : undefined,
66	              });
67	            }
68	            // Thinking
69	            else if (block.type === "thinking" && block.thinking) {
70	              messages.push({
71	                session_id: sessionId,
72	                checkpoint_id: checkpointId,
73	                message_type: "thinking",
74	                role: "assistant",
75	                thinking: block.thinking,
76	                message_index: messageIndex++,
77	                timestamp: entry.timestamp ? new Date(entry.timestamp).getTime() : undefined,
78	              });
79	            }
80	            // Tool use
81	            else if (block.type === "tool_use") {
82	              messages.push({
83	                session_id: sessionId,
84	                checkpoint_id: checkpointId,
85	                message_type: "tool_use",
86	                tool_name: block.name,
87	                tool_input: block.input ? JSON.stringify(block.input) : undefined,
88	                message_index: messageIndex++,
89	                timestamp: entry.timestamp ? new Date(entry.timestamp).getTime() : undefined,
90	              });
91	            }
92	          }
93	        }
94	      }
95	
96	      // Tool results
97	      else if (entry.type === "tool_result" && entry.message) {
98	        const content = typeof entry.message === "string"
99	          ? entry.message
100	          : entry.message.content || JSON.stringify(entry.message);
101	
102	        messages.push({
103	          session_id: sessionId,
104	          checkpoint_id: checkpointId,
105	          message_type: "tool_result",
106	          content: content,
107	          message_index: messageIndex++,
108	          timestamp: entry.timestamp ? new Date(entry.timestamp).getTime() : undefined,
109	        });
110	      }
111	    } catch {
112	      // Skip invalid JSON lines
113	      continue;
114	    }
115	  }
116	
117	  return messages;
118	}
