208	/**
209	 * Incrementally sync checkpoints from git to database
210	 * Only processes checkpoints that aren't already in the DB
211	 */
212	export async function syncCheckpoints(repo: GitRepo): Promise<SyncResult> {
213	  const syncStart = Date.now();
214	  const result: SyncResult = {
215	    synced: 0,
216	    skipped: 0,
217	    failed: 0,
218	    total: 0,
219	    duration: 0,
220	  };
221	
222	  // 1. Get known checkpoint IDs from database
223	  const knownCheckpoints = getKnownCheckpointIds();
224	  console.log(`   Database has ${knownCheckpoints.size} checkpoints`);
225	
226	  // 2. Scan git for current checkpoint IDs (fast - no metadata parsing)
227	  const currentCheckpoints = await scanCheckpointIds(repo);
228	  console.log(`   Git has ${currentCheckpoints.size} checkpoints`);
229	
230	  // 3. Find NEW checkpoints (set difference)
231	  const newCheckpointIds = Array.from(currentCheckpoints).filter(
232	    (id) => !knownCheckpoints.has(id)
233	  );
234	
235	  result.total = currentCheckpoints.size;
236	
237	  if (newCheckpointIds.length === 0) {
238	    console.log(`   Already up to date`);
239	    result.duration = Date.now() - syncStart;
240	    return result;
241	  }
242	
243	  console.log(`   Syncing ${newCheckpointIds.length} new checkpoints...`);
244	
245	  // Initialize GitHub CLI (optional - for PR enrichment)
246	  const gh = new GitHubCLI(".");
247	  const ghAvailable = await gh.isAvailable();
248	
249	  // 4. Process NEW checkpoints in batches
250	  const BATCH_SIZE = 10;
251	  for (let i = 0; i < newCheckpointIds.length; i += BATCH_SIZE) {
252	    const batch = newCheckpointIds.slice(i, i + BATCH_SIZE);
253	
254	    await Promise.all(
255	      batch.map(async (checkpointId) => {
256	        try {
257	          // Fetch checkpoint metadata
258	          const checkpoint = await getCheckpoint(repo, checkpointId);
259	          if (!checkpoint) {
260	            result.skipped++;
261	            return;
262	          }
263	
264	          // Fix created_at timestamp - read from first session if not in summary
265	          if (!checkpoint.metadata.created_at && checkpoint.metadata.sessions && checkpoint.metadata.sessions.length > 0) {
266	            try {
267	              // Session paths in metadata have format like "/52/f35895d802/0/metadata.json"
268	              // Strip leading slash for git readBlob
269	              const firstSession = checkpoint.metadata.sessions[0];
270	              const sessionMetadataPath = (firstSession.metadata || "").replace(/^\//, "");
271	
272	              if (sessionMetadataPath) {
273	                const sessionMetadataJson = await repo.readBlob(sessionMetadataPath, "entire/checkpoints/v1");
274	                const sessionMetadata = JSON.parse(sessionMetadataJson);
275	                if (sessionMetadata.created_at) {
276	                  checkpoint.metadata.created_at = sessionMetadata.created_at;
277	                }
278	              }
279	            } catch (error) {
280	              console.warn(`   Could not read session metadata for ${checkpointId}:`, error);
281	            }
282	          }
283	
284	          // Enrich with commit info (if commit hash available or can be found)
285	          let commitHash = checkpoint.metadata.commit_hash;
286	
287	          // Try reverse lookup if not in metadata
288	          if (!commitHash) {
289	            const foundHash = await repo.findCommitByCheckpointId(checkpointId);
290	            if (foundHash) {
291	              commitHash = foundHash;
292	              checkpoint.metadata.commit_hash = commitHash;
293	            }
294	          }
295	
296	          // Get commit details if we have a hash
297	          if (commitHash) {
298	            try {
299	              console.log(`   Fetching commit info for ${commitHash.slice(0, 8)}...`);
300	              const commitInfo = await repo.getCommitInfo(commitHash);
301	              if (commitInfo) {
302	                checkpoint.commitInfo = commitInfo;
303	
304	                // If we still don't have created_at, use commit date as fallback
305	                if (!checkpoint.metadata.created_at && commitInfo.date) {
306	                  checkpoint.metadata.created_at = commitInfo.date;
307	                  console.log(`   Using commit date for ${checkpointId}`);
308	                }
309	              }
310	
311	              // Get diff stats
312	              try {
313	                const diff = await repo.getCommitDiff(commitHash);
314	                const diffStats = parseDiffStats(diff);
315	                checkpoint.metadata.diff_stats = diffStats;
316	              } catch {
317	                // Diff might not be available
318	                checkpoint.metadata.diff_stats = { additions: 0, deletions: 0 };
319	              }
320	
321	              // Get PR info (if GitHub CLI available)
322	              if (ghAvailable) {
323	                try {
324	                  const prInfo = await gh.findPRForCommit(commitHash);
325	                  if (prInfo) {
326	                    checkpoint.pullRequest = prInfo;
327	                  }
328	                } catch {
329	                  // PR lookup failed, skip
330	                }
331	              }
332	            } catch (error) {
333	              console.warn(`   Failed to enrich checkpoint ${checkpointId}:`, error);
334	            }
335	          }
336	
337	          // Insert checkpoint into database
338	          upsertCheckpoint(checkpoint);
339	
340	          // Sync all sessions for this checkpoint
341	          if (checkpoint.metadata.sessions && checkpoint.metadata.sessions.length > 0) {
342	            for (let sessionIdx = 0; sessionIdx < checkpoint.metadata.sessions.length; sessionIdx++) {
343	              try {
344	                // Read session metadata
345	                const sessionMetadataJson = await readSessionMetadata(repo, checkpoint.path, sessionIdx);
346	                const sessionMetadata = JSON.parse(sessionMetadataJson);
347	
348	                // Read full transcript
349	                const transcriptJsonl = await readTranscript(repo, checkpoint.path, sessionIdx);
350	
351	                // Extract plain text for searching
352	                const transcriptText = extractPlainText(transcriptJsonl);
353	
354	                // Analyze transcript
355	                const { messageCount, toolUseCount } = analyzeTranscript(transcriptJsonl);
356	
357	                // Create session data
358	                const sessionData: SessionData = {
359	                  session_id: sessionMetadata.session_id,
360	                  checkpoint_id: checkpointId,
361	                  session_index: sessionIdx,
362	                  created_at: new Date(sessionMetadata.created_at).getTime(),
363	                  agent: sessionMetadata.agent,
364	                  strategy: sessionMetadata.strategy,
365	                  transcript_jsonl: transcriptJsonl,
366	                  transcript_text: transcriptText,
367	                  message_count: messageCount,
368	                  tool_use_count: toolUseCount,
369	                };
370	
371	                // Insert session into database
372	                upsertSession(sessionData);
373	
374	                // Parse and store individual messages
375	                const messages = parseTranscriptMessages(
376	                  transcriptJsonl,
377	                  sessionMetadata.session_id,
378	                  checkpointId
379	                );
380	
381	                // Delete old messages if any (for resync)
382	                deleteSessionMessages(sessionMetadata.session_id);
383	
384	                // Insert all messages
385	                for (const message of messages) {
386	                  insertMessage(message);
387	                }
388	              } catch (error) {
389	                console.warn(`   Failed to sync session ${checkpointId}/${sessionIdx}:`, error);
390	              }
391	            }
392	          }
393	
394	          result.synced++;
395	        } catch (error) {
396	          console.error(`   Failed to process checkpoint ${checkpointId}:`, error);
397	          result.failed++;
398	        }
399	      })
400	    );
401	
402	    // Progress indicator
403	    const processed = Math.min(i + BATCH_SIZE, newCheckpointIds.length);
404	    if (newCheckpointIds.length > 20) {
405	      console.log(`   Progress: ${processed}/${newCheckpointIds.length}`);
406	    }
407	  }
408	
409	  // 5. Update sync state
410	  const db = getDatabase();
411	  db.prepare(
412	    "INSERT OR REPLACE INTO sync_state (key, value, updated_at) VALUES (?, ?, ?)"
413	  ).run("last_sync", new Date().toISOString(), Date.now());
414	
415	  result.duration = Date.now() - syncStart;
416	
417	  console.log(
418	    `   Synced ${result.synced} checkpoints in ${result.duration}ms`
419	  );
420	  if (result.failed > 0) {
421	    console.warn(`   Failed to sync ${result.failed} checkpoints`);
422	  }
423	
424	  return result;
425	}
426	
427	/**
428	 * Full resync - clears database and resyncs all checkpoints
429	 * Use sparingly (e.g., after schema changes or corruption)
430	 */
431	export async function fullResync(repo: GitRepo): Promise<SyncResult> {
432	  console.log("Performing full database resync...");
433	
434	  const db = getDatabase();
435	
436	  // Clear all checkpoint data
437	  db.exec(`
438	    DELETE FROM checkpoint_files;
439	    DELETE FROM commits;
440	    DELETE FROM checkpoints;
441	    DELETE FROM sync_state WHERE key = 'last_sync';
442	  `);
443	
444	  console.log("   Database cleared");
445	
446	  // Perform sync (will treat all checkpoints as new)
447	  return await syncCheckpoints(repo);
448	}
449	
450	/**
451	 * Get last sync time
452	 */
453	export function getLastSyncTime(): Date | null {
454	  const db = getDatabase();
455	  const row = db.prepare("SELECT value FROM sync_state WHERE key = 'last_sync'").get() as any;
456	
457	  if (!row || !row.value) {
458	    return null;
459	  }
460	
461	  return new Date(row.value as string);
462	}
463	
464	/**
465	 * Background sync job - can be called periodically
466	 */
467	export async function backgroundSync(repo: GitRepo) {
468	  const lastSync = getLastSyncTime();
469	  const now = new Date();
470	
471	  // Only sync if it's been more than 5 minutes since last sync
472	  if (lastSync && now.getTime() - lastSync.getTime() < 5 * 60 * 1000) {
473	    return null;
474	  }
475	
476	  console.log("Running background sync...");
477	  const result = await syncCheckpoints(repo);
478	
479	  if (result.synced > 0) {
480	    console.log(`   Added ${result.synced} new checkpoints`);
481	  }
482	
483	  return result;
484	}
