// Incremental checkpoint synchronization

import { GitRepo } from "../git/repo.ts";
import { scanCheckpointIds, getCheckpoint } from "../git/tree.ts";
import { getKnownCheckpointIds, upsertCheckpoint } from "./checkpoints.ts";
import { upsertSession, type SessionData } from "./sessions.ts";
import { insertMessage, deleteSessionMessages, type Message } from "./messages.ts";
import { getDatabase } from "./schema.ts";
import { GitHubCLI } from "../github/cli.ts";
import { parseDiffStats } from "../git/diff-parser.ts";
import { readTranscript, readSessionMetadata } from "../parser/transcript.ts";

export interface SyncResult {
  synced: number;
  skipped: number;
  failed: number;
  total: number;
  duration: number;
}

/**
 * Parse JSONL transcript into individual messages
 */
function parseTranscriptMessages(
  jsonl: string,
  sessionId: string,
  checkpointId: string
): Message[] {
  const lines = jsonl.split("\n").filter((line) => line.trim());
  const messages: Message[] = [];
  let messageIndex = 0;

  for (const line of lines) {
    try {
      const entry = JSON.parse(line);

      // User messages
      if (entry.type === "user" && entry.message?.content) {
        messages.push({
          session_id: sessionId,
          checkpoint_id: checkpointId,
          message_type: "user",
          role: "user",
          content: typeof entry.message.content === "string"
            ? entry.message.content
            : JSON.stringify(entry.message.content),
          message_index: messageIndex++,
          timestamp: entry.timestamp ? new Date(entry.timestamp).getTime() : undefined,
        });
      }

      // Assistant messages
      else if (entry.type === "assistant" && entry.message?.content) {
        if (Array.isArray(entry.message.content)) {
          for (const block of entry.message.content) {
            // Text content
            if (block.type === "text" && block.text) {
              messages.push({
                session_id: sessionId,
                checkpoint_id: checkpointId,
                message_type: "assistant",
                role: "assistant",
                content: block.text,
                message_index: messageIndex++,
                timestamp: entry.timestamp ? new Date(entry.timestamp).getTime() : undefined,
              });
            }
            // Thinking
            else if (block.type === "thinking" && block.thinking) {
              messages.push({
                session_id: sessionId,
                checkpoint_id: checkpointId,
                message_type: "thinking",
                role: "assistant",
                thinking: block.thinking,
                message_index: messageIndex++,
                timestamp: entry.timestamp ? new Date(entry.timestamp).getTime() : undefined,
              });
            }
            // Tool use
            else if (block.type === "tool_use") {
              messages.push({
                session_id: sessionId,
                checkpoint_id: checkpointId,
                message_type: "tool_use",
                tool_name: block.name,
                tool_input: block.input ? JSON.stringify(block.input) : undefined,
                message_index: messageIndex++,
                timestamp: entry.timestamp ? new Date(entry.timestamp).getTime() : undefined,
              });
            }
          }
        }
      }

      // Tool results
      else if (entry.type === "tool_result" && entry.message) {
        const content = typeof entry.message === "string"
          ? entry.message
          : entry.message.content || JSON.stringify(entry.message);

        messages.push({
          session_id: sessionId,
          checkpoint_id: checkpointId,
          message_type: "tool_result",
          content: content,
          message_index: messageIndex++,
          timestamp: entry.timestamp ? new Date(entry.timestamp).getTime() : undefined,
        });
      }
    } catch {
      // Skip invalid JSON lines
      continue;
    }
  }

  return messages;
}

/**
 * Extract plain text from JSONL transcript for indexing
 * Handles the actual entire CLI format
 */
function extractPlainText(jsonl: string): string {
  const lines = jsonl.split("\n").filter((line) => line.trim());
  const textParts: string[] = [];

  for (const line of lines) {
    try {
      const entry = JSON.parse(line);

      // User messages: entry.message.content (string)
      if (entry.type === "user" && entry.message?.content) {
        if (typeof entry.message.content === "string") {
          textParts.push(entry.message.content);
        }
      }

      // Assistant messages: entry.message.content (array of content blocks)
      else if (entry.type === "assistant" && entry.message?.content) {
        if (Array.isArray(entry.message.content)) {
          for (const block of entry.message.content) {
            // Text blocks
            if (block.type === "text" && block.text) {
              textParts.push(block.text);
            }
            // Thinking blocks
            else if (block.type === "thinking" && block.thinking) {
              textParts.push(block.thinking);
            }
            // Tool use blocks
            else if (block.type === "tool_use" && block.input) {
              textParts.push(JSON.stringify(block.input));
            }
          }
        }
      }

      // Tool results: entry.message (for tool result type)
      else if (entry.type === "tool_result" && entry.message) {
        if (typeof entry.message === "string") {
          textParts.push(entry.message);
        } else if (entry.message.content) {
          textParts.push(entry.message.content);
        }
      }

      // Generic messages with text field
      else if (entry.type === "message" && entry.text) {
        textParts.push(entry.text);
      }
    } catch {
      // Skip invalid JSON lines
      continue;
    }
  }

  return textParts.join("\n");
}

/**
 * Count messages and tool uses in transcript
 */
function analyzeTranscript(jsonl: string): { messageCount: number; toolUseCount: number } {
  const lines = jsonl.split("\n").filter((line) => line.trim());
  let messageCount = 0;
  let toolUseCount = 0;

  for (const line of lines) {
    try {
      const entry = JSON.parse(line);

      if (entry.type === "user" || entry.type === "assistant") {
        messageCount++;
      }

      if (entry.type === "tool_use" || entry.toolUseID) {
        toolUseCount++;
      }
    } catch {
      continue;
    }
  }

  return { messageCount, toolUseCount };
}

/**
 * Incrementally sync checkpoints from git to database
 * Only processes checkpoints that aren't already in the DB
 */
export async function syncCheckpoints(repo: GitRepo): Promise<SyncResult> {
  const syncStart = Date.now();
  const result: SyncResult = {
    synced: 0,
    skipped: 0,
    failed: 0,
    total: 0,
    duration: 0,
  };

  // 1. Get known checkpoint IDs from database
  const knownCheckpoints = getKnownCheckpointIds();
  console.log(`   Database has ${knownCheckpoints.size} checkpoints`);

  // 2. Scan git for current checkpoint IDs (fast - no metadata parsing)
  const currentCheckpoints = await scanCheckpointIds(repo);
  console.log(`   Git has ${currentCheckpoints.size} checkpoints`);

  // 3. Find NEW checkpoints (set difference)
  const newCheckpointIds = Array.from(currentCheckpoints).filter(
    (id) => !knownCheckpoints.has(id)
  );

  result.total = currentCheckpoints.size;

  if (newCheckpointIds.length === 0) {
    console.log(`   Already up to date`);
    result.duration = Date.now() - syncStart;
    return result;
  }

  console.log(`   Syncing ${newCheckpointIds.length} new checkpoints...`);

  // Initialize GitHub CLI (optional - for PR enrichment)
  const gh = new GitHubCLI(".");
  const ghAvailable = await gh.isAvailable();

  // 4. Process NEW checkpoints in batches
  const BATCH_SIZE = 10;
  for (let i = 0; i < newCheckpointIds.length; i += BATCH_SIZE) {
    const batch = newCheckpointIds.slice(i, i + BATCH_SIZE);

    await Promise.all(
      batch.map(async (checkpointId) => {
        try {
          // Fetch checkpoint metadata
          const checkpoint = await getCheckpoint(repo, checkpointId);
          if (!checkpoint) {
            result.skipped++;
            return;
          }

          // Fix created_at timestamp - read from first session if not in summary
          if (!checkpoint.metadata.created_at && checkpoint.metadata.sessions && checkpoint.metadata.sessions.length > 0) {
            try {
              // Session paths in metadata have format like "/52/f35895d802/0/metadata.json"
              // Strip leading slash for git readBlob
              const firstSession = checkpoint.metadata.sessions[0];
              const sessionMetadataPath = (firstSession.metadata || "").replace(/^\//, "");

              if (sessionMetadataPath) {
                const sessionMetadataJson = await repo.readBlob(sessionMetadataPath, "entire/checkpoints/v1");
                const sessionMetadata = JSON.parse(sessionMetadataJson);
                if (sessionMetadata.created_at) {
                  checkpoint.metadata.created_at = sessionMetadata.created_at;
                }
              }
            } catch (error) {
              console.warn(`   Could not read session metadata for ${checkpointId}:`, error);
            }
          }

          // Enrich with commit info (if commit hash available or can be found)
          let commitHash = checkpoint.metadata.commit_hash;

          // Try reverse lookup if not in metadata
          if (!commitHash) {
            const foundHash = await repo.findCommitByCheckpointId(checkpointId);
            if (foundHash) {
              commitHash = foundHash;
              checkpoint.metadata.commit_hash = commitHash;
            }
          }

          // Get commit details if we have a hash
          if (commitHash) {
            try {
              console.log(`   Fetching commit info for ${commitHash.slice(0, 8)}...`);
              const commitInfo = await repo.getCommitInfo(commitHash);
              if (commitInfo) {
                checkpoint.commitInfo = commitInfo;

                // If we still don't have created_at, use commit date as fallback
                if (!checkpoint.metadata.created_at && commitInfo.date) {
                  checkpoint.metadata.created_at = commitInfo.date;
                  console.log(`   Using commit date for ${checkpointId}`);
                }
              }

              // Get diff stats
              try {
                const diff = await repo.getCommitDiff(commitHash);
                const diffStats = parseDiffStats(diff);
                checkpoint.metadata.diff_stats = diffStats;
              } catch {
                // Diff might not be available
                checkpoint.metadata.diff_stats = { additions: 0, deletions: 0 };
              }

              // Get PR info (if GitHub CLI available)
              if (ghAvailable) {
                try {
                  const prInfo = await gh.findPRForCommit(commitHash);
                  if (prInfo) {
                    checkpoint.pullRequest = prInfo;
                  }
                } catch {
                  // PR lookup failed, skip
                }
              }
            } catch (error) {
              console.warn(`   Failed to enrich checkpoint ${checkpointId}:`, error);
            }
          }

          // Insert checkpoint into database
          upsertCheckpoint(checkpoint);

          // Sync all sessions for this checkpoint
          if (checkpoint.metadata.sessions && checkpoint.metadata.sessions.length > 0) {
            for (let sessionIdx = 0; sessionIdx < checkpoint.metadata.sessions.length; sessionIdx++) {
              try {
                // Read session metadata
                const sessionMetadataJson = await readSessionMetadata(repo, checkpoint.path, sessionIdx);
                const sessionMetadata = JSON.parse(sessionMetadataJson);

                // Read full transcript
                const transcriptJsonl = await readTranscript(repo, checkpoint.path, sessionIdx);

                // Extract plain text for searching
                const transcriptText = extractPlainText(transcriptJsonl);

                // Analyze transcript
                const { messageCount, toolUseCount } = analyzeTranscript(transcriptJsonl);

                // Create session data
                const sessionData: SessionData = {
                  session_id: sessionMetadata.session_id,
                  checkpoint_id: checkpointId,
                  session_index: sessionIdx,
                  created_at: new Date(sessionMetadata.created_at).getTime(),
                  agent: sessionMetadata.agent,
                  strategy: sessionMetadata.strategy,
                  transcript_jsonl: transcriptJsonl,
                  transcript_text: transcriptText,
                  message_count: messageCount,
                  tool_use_count: toolUseCount,
                };

                // Insert session into database
                upsertSession(sessionData);

                // Parse and store individual messages
                const messages = parseTranscriptMessages(
                  transcriptJsonl,
                  sessionMetadata.session_id,
                  checkpointId
                );

                // Delete old messages if any (for resync)
                deleteSessionMessages(sessionMetadata.session_id);

                // Insert all messages
                for (const message of messages) {
                  insertMessage(message);
                }
              } catch (error) {
                console.warn(`   Failed to sync session ${checkpointId}/${sessionIdx}:`, error);
              }
            }
          }

          result.synced++;
        } catch (error) {
          console.error(`   Failed to process checkpoint ${checkpointId}:`, error);
          result.failed++;
        }
      })
    );

    // Progress indicator
    const processed = Math.min(i + BATCH_SIZE, newCheckpointIds.length);
    if (newCheckpointIds.length > 20) {
      console.log(`   Progress: ${processed}/${newCheckpointIds.length}`);
    }
  }

  // 5. Update sync state
  const db = getDatabase();
  db.prepare(
    "INSERT OR REPLACE INTO sync_state (key, value, updated_at) VALUES (?, ?, ?)"
  ).run("last_sync", new Date().toISOString(), Date.now());

  result.duration = Date.now() - syncStart;

  console.log(
    `   Synced ${result.synced} checkpoints in ${result.duration}ms`
  );
  if (result.failed > 0) {
    console.warn(`   Failed to sync ${result.failed} checkpoints`);
  }

  return result;
}

/**
 * Full resync - clears database and resyncs all checkpoints
 * Use sparingly (e.g., after schema changes or corruption)
 */
export async function fullResync(repo: GitRepo): Promise<SyncResult> {
  console.log("Performing full database resync...");

  const db = getDatabase();

  // Clear all checkpoint data
  db.exec(`
    DELETE FROM checkpoint_files;
    DELETE FROM commits;
    DELETE FROM checkpoints;
    DELETE FROM sync_state WHERE key = 'last_sync';
  `);

  console.log("   Database cleared");

  // Perform sync (will treat all checkpoints as new)
  return await syncCheckpoints(repo);
}

/**
 * Get last sync time
 */
export function getLastSyncTime(): Date | null {
  const db = getDatabase();
  const row = db.prepare("SELECT value FROM sync_state WHERE key = 'last_sync'").get() as any;

  if (!row || !row.value) {
    return null;
  }

  return new Date(row.value as string);
}

/**
 * Background sync job - can be called periodically
 */
export async function backgroundSync(repo: GitRepo) {
  const lastSync = getLastSyncTime();
  const now = new Date();

  // Only sync if it's been more than 5 minutes since last sync
  if (lastSync && now.getTime() - lastSync.getTime() < 5 * 60 * 1000) {
    return null;
  }

  console.log("Running background sync...");
  const result = await syncCheckpoints(repo);

  if (result.synced > 0) {
    console.log(`   Added ${result.synced} new checkpoints`);
  }

  return result;
}

