// Git repository operations via CLI

import type { TreeEntry } from "../types/entire.ts";

export class GitRepo {
  constructor(private repoPath: string) {}

  /**
   * Execute git command
   */
  private async exec(args: string[]): Promise<string> {
    const cmd = new Deno.Command("git", {
      args: ["-C", this.repoPath, ...args],
      stdout: "piped",
      stderr: "piped",
    });

    const { code, stdout, stderr } = await cmd.output();

    if (code !== 0) {
      const error = new TextDecoder().decode(stderr);
      throw new Error(`Git command failed: ${error}`);
    }

    return new TextDecoder().decode(stdout);
  }

  /**
   * Check if branch exists
   */
  async branchExists(branch: string): Promise<boolean> {
    try {
      await this.exec(["rev-parse", "--verify", branch]);
      return true;
    } catch {
      return false;
    }
  }

  /**
   * List tree entries at path in branch
   */
  async listTree(path: string, branch: string): Promise<TreeEntry[]> {
    try {
      const output = await this.exec([
        "ls-tree",
        `${branch}:${path}`,
      ]);

      return output
        .split("\n")
        .filter((line) => line.trim())
        .map((line) => {
          const [meta, name] = line.split("\t");
          const [mode, type, hash] = meta.split(" ");
          return {
            mode,
            type: type as "blob" | "tree",
            hash,
            name,
          };
        });
    } catch {
      return [];
    }
  }

  /**
   * Read blob content from git
   */
  async readBlob(path: string, branch: string): Promise<string> {
    const output = await this.exec(["show", `${branch}:${path}`]);
    return output;
  }

  /**
   * Get current repository directory
   */
  async getRepoRoot(): Promise<string> {
    const output = await this.exec(["rev-parse", "--show-toplevel"]);
    return output.trim();
  }

  /**
   * Get remote URL (if any)
   */
  async getRemoteUrl(): Promise<string | null> {
    try {
      const output = await this.exec(["config", "--get", "remote.origin.url"]);
      return output.trim();
    } catch {
      return null;
    }
  }

  /**
   * Get git user name
   */
  async getUserName(): Promise<string | null> {
    try {
      const output = await this.exec(["config", "user.name"]);
      return output.trim();
    } catch {
      return null;
    }
  }

  /**
   * Get git user email
   */
  async getUserEmail(): Promise<string | null> {
    try {
      const output = await this.exec(["config", "user.email"]);
      return output.trim();
    } catch {
      return null;
    }
  }

  /**
   * Get diff for a specific file at a commit
   */
  async getDiff(commitHash: string, filePath: string): Promise<string | null> {
    try {
      const output = await this.exec([
        "diff",
        `${commitHash}^`,
        commitHash,
        "--",
        filePath,
      ]);
      return output || null;
    } catch {
      return null;
    }
  }

  /**
   * Get all diffs for a commit
   */
  async getCommitDiff(commitHash: string): Promise<string> {
    try {
      const output = await this.exec(["diff", `${commitHash}^`, commitHash]);
      return output;
    } catch (error) {
      throw new Error(`Failed to get diff for commit ${commitHash}: ${error}`);
    }
  }

  /**
   * Get commit metadata (message, author, date)
   */
  async getCommitInfo(commitHash: string): Promise<{
    message: string;
    author: string;
    email: string;
    date: string;
    hash: string;
  } | null> {
    try {
      // Format: subject%nauthor name%nauthor email%ncommit date%nhash
      const format = "%s%n%an%n%ae%n%cI%n%H";
      const output = await this.exec([
        "show",
        "-s",
        `--format=${format}`,
        commitHash,
      ]);

      const lines = output.trim().split("\n");
      if (lines.length < 5) return null;

      return {
        message: lines[0],
        author: lines[1],
        email: lines[2],
        date: lines[3],
        hash: lines[4],
      };
    } catch {
      return null;
    }
  }

  /**
   * Find commit by Entire-Checkpoint trailer
   */
  async findCommitByCheckpointId(checkpointId: string): Promise<string | null> {
    try {
      // Search all branches for commits with this checkpoint ID
      const output = await this.exec([
        "log",
        "--all",
        "--grep",
        `Entire-Checkpoint: ${checkpointId}`,
        "--format=%H",
        "-1",
      ]);
      const hash = output.trim();
      return hash || null;
    } catch {
      return null;
    }
  }
}

