// Navigate checkpoint sharded directory structure

import type { CheckpointInfo, CheckpointSummary } from "../types/entire.ts";
import { GitRepo } from "./repo.ts";
import { listShardPrefixes, pathToCheckpointId } from "../utils/shard.ts";
import { parseCheckpointSummary } from "../parser/metadata.ts";

const BRANCH = "entire/checkpoints/v1";

/**
 * Fast scan to get only checkpoint IDs (no metadata parsing)
 * Used for sync diffing to find new checkpoints
 */
export async function scanCheckpointIds(
  repo: GitRepo
): Promise<Set<string>> {
  const checkpointIds = new Set<string>();

  // Check if branch exists
  if (!(await repo.branchExists(BRANCH))) {
    return checkpointIds;
  }

  // List all shard prefixes (a0, a1, ..., ff)
  const shards = listShardPrefixes();

  for (const shard of shards) {
    try {
      // List checkpoint directories in this shard
      const entries = await repo.listTree(shard, BRANCH);

      for (const entry of entries) {
        if (entry.type === "tree") {
          // Just collect the ID, don't parse metadata
          const checkpointId = pathToCheckpointId(`${shard}/${entry.name}`);
          checkpointIds.add(checkpointId);
        }
      }
    } catch {
      // Skip shards that don't exist
      continue;
    }
  }

  return checkpointIds;
}

/**
 * Scan all checkpoints in the repository
 */
export async function scanCheckpoints(
  repo: GitRepo
): Promise<CheckpointInfo[]> {
  const checkpoints: CheckpointInfo[] = [];

  // Check if branch exists
  if (!(await repo.branchExists(BRANCH))) {
    return [];
  }

  // List all shard prefixes (a0, a1, ..., ff)
  const shards = listShardPrefixes();

  for (const shard of shards) {
    // List checkpoint directories in this shard
    const entries = await repo.listTree(shard, BRANCH);

    for (const entry of entries) {
      if (entry.type === "tree") {
        try {
          // Read metadata.json for this checkpoint
          const metadataPath = `${shard}/${entry.name}/metadata.json`;
          const metadataContent = await repo.readBlob(metadataPath, BRANCH);
          const metadata = parseCheckpointSummary(metadataContent);

          // Count sessions
          const sessionCount = metadata.sessions?.length || 0;

          checkpoints.push({
            id: pathToCheckpointId(`${shard}/${entry.name}`),
            path: `${shard}/${entry.name}`,
            metadata,
            sessionCount,
          });
        } catch (error) {
          console.error(`Failed to read checkpoint ${shard}/${entry.name}:`, error);
          // Skip invalid checkpoints
        }
      }
    }
  }

  // Sort by created_at (newest first)
  checkpoints.sort((a, b) => {
    const dateA = new Date(a.metadata.created_at).getTime();
    const dateB = new Date(b.metadata.created_at).getTime();
    return dateB - dateA;
  });

  return checkpoints;
}

/**
 * Get checkpoint by ID
 */
export async function getCheckpoint(
  repo: GitRepo,
  checkpointId: string
): Promise<CheckpointInfo | null> {
  const shard = checkpointId.slice(0, 2);
  const suffix = checkpointId.slice(2);
  const path = `${shard}/${suffix}`;

  try {
    const metadataPath = `${path}/metadata.json`;
    const metadataContent = await repo.readBlob(metadataPath, BRANCH);
    const metadata = parseCheckpointSummary(metadataContent);
    const sessionCount = metadata.sessions?.length || 0;

    return {
      id: checkpointId,
      path,
      metadata,
      sessionCount,
    };
  } catch {
    return null;
  }
}

