{
  "name": "chisme-validate",
  "private": true,
  "type": "module"
}

import { Database } from "bun:sqlite";
import { parseArgs } from "node:util";

const db = new Database(":memory:");
db.exec("PRAGMA journal_mode=WAL;");

// --- sqlite version ---
console.log("sqlite_version:", (db.query("select sqlite_version() as v").get() as any).v);

// --- FTS5 (must be built into bun:sqlite) ---
try {
  db.exec(`CREATE VIRTUAL TABLE fts USING fts5(pk UNINDEXED, body, tokenize='porter unicode61');`);
  db.exec(`INSERT INTO fts(pk, body) VALUES ('1','add auth middleware to the server'), ('2','fix race condition in the queue');`);
  const kw = db
    .query(`SELECT pk, bm25(fts) AS score, snippet(fts,1,'[',']','...',6) AS snip FROM fts WHERE fts MATCH ? ORDER BY score`)
    .all("auth");
  console.log("FTS5 OK:", JSON.stringify(kw));
} catch (e) {
  console.log("FTS5 FAILED:", String(e));
}

// --- util.parseArgs ---
try {
  const { values, positionals } = parseArgs({
    args: ["search", "auth thing", "--json", "--limit", "10", "--repo", "*"],
    allowPositionals: true,
    options: { json: { type: "boolean" }, limit: { type: "string" }, repo: { type: "string" } },
  });
  console.log("parseArgs OK:", JSON.stringify({ values, positionals }));
} catch (e) {
  console.log("parseArgs FAILED:", String(e));
}

// --- sqlite-vec loadable extension via bun:sqlite ---
try {
  const { getLoadablePath } = await import("sqlite-vec");
  const extPath = getLoadablePath();
  console.log("sqlite-vec loadable path:", extPath);
  db.loadExtension(extPath);
  console.log("vec_version:", (db.query("select vec_version() as v").get() as any).v);

  db.exec(`CREATE VIRTUAL TABLE vec USING vec0(id INTEGER PRIMARY KEY, embedding FLOAT[4]);`);
  const v1 = new Float32Array([0.1, 0.2, 0.3, 0.4]);
  const v2 = new Float32Array([0.9, 0.8, 0.1, 0.0]);
  db.query(`INSERT INTO vec(id, embedding) VALUES (?, ?)`).run(1, new Uint8Array(v1.buffer));
  db.query(`INSERT INTO vec(id, embedding) VALUES (?, ?)`).run(2, new Uint8Array(v2.buffer));
  const q = new Float32Array([0.1, 0.2, 0.3, 0.45]);
  const knn = db
    .query(`SELECT id, distance FROM vec WHERE embedding MATCH ? AND k = 3 ORDER BY distance`)
    .all(new Uint8Array(q.buffer));
  console.log("sqlite-vec OK:", JSON.stringify(knn));
} catch (e) {
  console.log("sqlite-vec FAILED:", String(e));
}

